import json
import os
import re
import pyshark
import asyncio
from collections import defaultdict


from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output, log_result
)

from taf.rfrl.procedures.resources.python.parser.exceptions import (
    ParameterNotFound,
    PcapDataNotFound,
    IncorrectParameterValue,
)


@log_input_and_output
def check_L2RtPoolDeployment_parameters(parameters_to_check, path_to_pcap, path_to_json=None):
    """
    Checks if provided parameters (parameters_to_check) exist in pcap file (path_to_pcap) and have proper value.

    :param parameters_to_check: parameters dict that should exist in pcap file, e.g.:
                                {'slowPrbPoolingFddFr1EnhAllowed': 'false',
                                'spatialStreamPoolingAllowed': 'false',}
    :type parameters_to_check: dict
    :param path_to_pcap: absolute path with filename and extension to pcap file, e.g. /tmp/gnb_logs.pcap
    :type path_to_pcap: str
    :param path_to_json: absolute path with filename and extension to json file witch will be created based on pcap.
                         Default value None means, json file path and name will be the same as provided pcap file.
    :type path_to_json: str or None

    :raises ParameterNotFound: if parameter to check is not found in pcap parameters list
    :raises IncorrectParameterValue: if parameter has incorrect value
    """
    parameters_from_pcap = _get_L2RtPoolDeployment_parameters_from_pcap(path_to_pcap=path_to_pcap,
                                                                        path_to_json=path_to_json)

    for param, value in parameters_to_check.items():
        try:
            assert parameters_from_pcap[param] == value
        except KeyError:
            raise ParameterNotFound("Parameter '{}' is not found in pcap parameters list".format(param))
        except AssertionError:
            raise IncorrectParameterValue("Incorrect '{}' parameter value. Actual '{}', should be '{}'".
                                          format(param, parameters_from_pcap[param], value))


def filter_pcap(pcap_path, display_filter, filtered_pcap_path=None, use_ek=False, include_raw=False):
    """
    Filters a PCAP file using a wireshark display filter and optionally saves the filtered results to a new file.
    :param pcap_path: Absolute path to the input PCAP file e.g. '/home/ute/example.pcap'
    :type pcap_path: str
    :param display_filter: Wireshark display filter to apply, e.g. 'ecpri' or 'ecpri.measurementid == 0x01'
    :type display_filter: str
    :param filtered_pcap_path: (optional) Absolute path to save the filtered PCAP file e.g. '/home/ute/filtered.pcap', default None means no saving
    :type filtered_pcap_path: str or None
    :param use_ek: (optional) If True, the output file will be in JSON format, designed for compatibility with ElasticSearch and Kibana
    :type use_ek: bool
    :param include_raw: (optional)(works only with use_ek=True) If True, the output file will include raw packet data, default False
    :type include_raw: bool
    :return: Generator yielding pyshark.Packet objects that match the display filter.
    """
    if filtered_pcap_path:
        _filter_and_save_pcap(pcap_path, display_filter=display_filter, filtered_pcap_path=filtered_pcap_path)
        pcap_path = filtered_pcap_path
        display_filter = None

    return _filter_pcap(pcap_path, display_filter=display_filter, use_ek=use_ek, include_raw=include_raw)


def group_ecpri_delay_measurement_sessions(pcap_capture):
    """
    Groups eCPRI delay measurement sessions based on the 'Measurement ID' field.
    Values are read and processed in chronological order. The end of a session is determined by a packet with new 'Measurement ID'.

    :param pcap_capture: Filtered PCAP (filtered using the Wireshark expression 'ecpri.type == 0x05')
    :type pcap_capture: pyshark.FileCapture object
    :return: Dictionary, where each key represents a session number and the value is a list of packets representing the session.
            e.g. {1: [pyshark.Packet, pyshark.Packet], 2: [pyshark.Packet, pyshark.Packet]}
    :rtype: dict
    """
    grouped_sessions = defaultdict(list)
    last_measurement_id = None
    session_number = 1
    for packet in pcap_capture:
        current_measurement_id = packet.ecpri.measurementid
        if current_measurement_id != last_measurement_id and last_measurement_id is not None:
            session_number += 1

        grouped_sessions[session_number].append(packet)
        last_measurement_id = current_measurement_id

    for packets in grouped_sessions.values():
        _verify_session_measurement_id(packets)

    return grouped_sessions


@log_input_and_output
def _get_L2RtPoolDeployment_parameters_from_pcap(path_to_pcap, path_to_json=None):
    """
    Gets L2RtPoolDeployment from pcap file.

    :param path_to_pcap: absolute path with filename and extension to pcap file, e.g. /tmp/gnb_logs.pcap
    :type path_to_pcap: str
    :param path_to_json: absolute path with filename and extension to json file witch will be created based on pcap.
                         Default value None means, json file path and name will be the same as provided pcap file.
    :type path_to_json: str or None

    :return: dict of L2RtPoolDeployment parameters found in pcap file, e.g.:
                                {'slowPrbPoolingFddFr1EnhAllowed': 'false',
                                'spatialStreamPoolingAllowed': 'false',
                                'subcellDeactivationDlAllowed': 'false'}
    :rtype: dict

    :raises PcapDataNotFound: if JSON file created based on PCAP does not contain aasyslog data
    """
    path_to_json = path_to_pcap.rsplit(".", 1)[0] + ".json" if not path_to_json else path_to_json
    _convert_pcap_to_json_file(path_to_pcap=path_to_pcap,
                               path_to_json=path_to_json,
                               filter="-Y 'aasyslog.print contains PoolMgmtService.cpp'")
    aasyslog = _get_aasyslogs_data(path_to_json=path_to_json)

    if aasyslog == "":
        raise PcapDataNotFound("JSON file {} created based on PCAP {} does not contain aasyslog data".
                               format(path_to_json, path_to_pcap))

    return _create_dict_of_parameters(_get_list_of_L2RtPoolDeployment_parameters(aasyslog))


def _convert_pcap_to_json_file(path_to_pcap, path_to_json, filter=None):
    filtering_phrase = filter if filter else ""

    os.system("""tshark {} -r {} -T json > {}""".format(filtering_phrase, path_to_pcap, path_to_json))


@log_input_and_output
def _get_aasyslogs_data(path_to_json):
    with open(path_to_json, "r") as json_file:
        json_content = json.loads(json_file.read(), object_pairs_hook=_json_loads_convert_duplicated_keys_to_json_array)

        aasyslog = []
        for msg in json_content:
            aasyslog += dict(msg['_source']['layers']['aasyslog']).values()

    return _parse_aasyslog(_unpack_aasyslog_to_one_list(aasyslog))


def _unpack_aasyslog_to_one_list(aasyslog):
    aasyslog_list = []
    for elem in aasyslog:
        if isinstance(elem, list):
            aasyslog_list += elem
        else:
            aasyslog_list.append(elem)

    return aasyslog_list


def _parse_aasyslog(aasyslog_list):
    data = ""
    for elem in aasyslog_list:
        data += re.split(r'(c|h)pp:[1-9][0-9]*\s', elem)[-1]

    return data.replace("\r\n", "")


def _remove_log_scram_headers_from_aasyslog(aasyslog):
    aasyslog = re.sub(r'\[MSG\] Received from .{,40}: <LOG_SCRAM_\d+>', '', aasyslog)
    aasyslog = re.sub(r'</LOG_SCRAM_\d+>', '', aasyslog)
    return aasyslog


@log_input_and_output
def _get_list_of_L2RtPoolDeployment_parameters(aasyslog):
    aasyslog = _remove_log_scram_headers_from_aasyslog(aasyslog)
    return list(set((re.findall(
        r"""[a-z]\w+:\sboolean\s=\sfalse|[a-z]\w+:\sboolean\s=\strue|"[a-z]\w+":false|"[a-z]\w+":true""", aasyslog))))


def _create_dict_of_parameters(parameters_list):
    params_dict = {}
    for param in parameters_list:
        if ": boolean = " in param:
            param_name, param_value = param.split(": boolean = ")
        else:
            param_name, param_value = param.split(":")
            param_name = re.search(r"[a-z]\w+", param_name).group()

        if params_dict.get(param_name):
            raise IncorrectParameterValue(f"Parameter `{param_name}` is defined in PCAP file multiple times with "
                                          f"different values: '{params_dict[param_name]}' and '{param_value}'")
        params_dict[param_name] = param_value

    return params_dict


def _json_loads_convert_duplicated_keys_to_json_array(ordered_pairs):
    """
    Converts duplicated keys to JSON array.
    Function used as object_pairs_hook parameter in json.loads method.
    """
    conv_dict = {}
    for key, value in ordered_pairs:
        if key in conv_dict:
            if type(conv_dict[key]) is list:
                conv_dict[key].append(value)
            else:
                conv_dict[key] = [conv_dict[key], value]
        else:
            conv_dict[key] = value
    return conv_dict


def _verify_session_measurement_id(packets):
    """
    The passed packets should not include raw data. If they do, function will raise an exception.
    Verifies if the 'Measurement ID' field in eCPRI one-way delay measurement packets is the same.

    :param packets: List of packets without raw data representing one eCPRI delay measurement session.
    :type packets: list[pyshark.Packet objects]
    :raises IncorrectParameterValue: If 'Measurement ID' field in eCPRI one-way delay measurement session packets is not the same for each.
    """
    if not all(packet.ecpri.measurementid == packets[0].ecpri.measurementid for packet in packets):
        all_packets = '\n'.join([f"{packet.frame_info.time} - {packet.ecpri.measurementid}" for packet in packets])
        raise IncorrectParameterValue(f"Something went wrong with grouping eCPRI one-way delay measurement packets by sessions.\nAll packets "
                                      f"in a session should have the same Measurement ID. All verified packets:\n{all_packets}")


def _filter_pcap(pcap_path, display_filter, use_ek=False, include_raw=False):
    """
    Filters the PCAP file using the provided display filter and saves the results to a new file.

    :param pcap_path: Absolute path to the input PCAP file e.g. '/home/ute/example.pcap'
    :type pcap_path: str
    :param display_filter: Wireshark display filter to apply, e.g. 'ecpri' or 'ecpri.measurementid == 0x01'
    :type display_filter: str
    :param use_ek: (optional) If True, the output file will be in JSON format, designed for compatibility with ElasticSearch and Kibana
    :type use_ek: bool
    :param include_raw: (optional)(works only with use_ek=True) If True, the output file will include raw packet data, default False
    :type include_raw: bool
    :return: Generator yielding pyshark.Packet objects that match the display filter.
    """
    new_loop = asyncio.new_event_loop()
    watcher = asyncio.SafeChildWatcher()
    watcher.attach_loop(new_loop)
    asyncio.get_event_loop_policy().set_child_watcher(watcher)
    cap = pyshark.FileCapture(pcap_path, display_filter=display_filter, use_ek=use_ek, include_raw=include_raw, eventloop=new_loop)
    try:
        any_match = False
        for packet in cap:
            any_match = True
            yield packet

        if not any_match:
            log_result(f"Filtered pcap is empty. No matching packets found using the provided display filter = '{display_filter}'.")
    finally:
        new_loop.run_until_complete(cap.close_async())
        new_loop.close()


def _filter_and_save_pcap(pcap_path, display_filter, filtered_pcap_path):
    """
    Saves the filtered packets to a new PCAP file.

    :param pcap_path: Absolute path to the input PCAP file e.g. '/home/ute/example.pcap'
    :type pcap_path: str
    :param display_filter: Wireshark display filter to apply, e.g. 'ecpri' or 'ecpri.measurementid == 0x01'
    :type display_filter: str
    :param filtered_pcap_path: Absolute path to save the filtered PCAP file e.g. '/home/ute/filtered.pcap'
    :type filtered_pcap_path: str
    """
    cap = pyshark.FileCapture(pcap_path, display_filter=display_filter, output_file=filtered_pcap_path)
    try:
        cap.load_packets()
    finally:
        cap.close()
